begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('00005827-0000-4000-8000-000000000001'),('00005827-0000-4000-8000-000000000002');
insert into public.users(id) values ('00005827-0000-4000-8000-000000000001'),('00005827-0000-4000-8000-000000000002') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values ('00005827-0000-4000-8000-000000000011','Disposable voice job fixture',false,'00005827-0000-4000-8000-000000000001');
insert into public.workspace_members(ws_id,user_id,type) values ('00005827-0000-4000-8000-000000000011','00005827-0000-4000-8000-000000000001','MEMBER'),('00005827-0000-4000-8000-000000000011','00005827-0000-4000-8000-000000000002','MEMBER') on conflict do nothing;
insert into private.note_voice_jobs(id,ws_id,user_id,input_hash,timezone) values ('00005827-0000-4000-8000-000000000021','00005827-0000-4000-8000-000000000011','00005827-0000-4000-8000-000000000001',repeat('a',64),'UTC'),('00005827-0000-4000-8000-000000000022','00005827-0000-4000-8000-000000000011','00005827-0000-4000-8000-000000000002',repeat('b',64),'UTC');
select throws_ok($q$ update private.note_voice_jobs set status='completed' where id='00005827-0000-4000-8000-000000000021' $q$,'23514',null,'completion needs both artifact and transcript');
select throws_ok($q$ update private.note_voice_jobs set revision=0 where id='00005827-0000-4000-8000-000000000021' $q$,'23514',null,'revision must stay positive');
select throws_ok($q$ update private.note_voice_jobs set input_hash='invalid' where id='00005827-0000-4000-8000-000000000021' $q$,'23514',null,'hash is constrained');
select throws_ok($q$ update private.note_voice_jobs set artifact='[]'::jsonb where id='00005827-0000-4000-8000-000000000021' $q$,'23514',null,'artifact is an object');
select throws_ok($q$ insert into private.note_voice_jobs select * from private.note_voice_jobs where id='00005827-0000-4000-8000-000000000021' $q$,'23505',null,'idempotency identity is unique');
select set_config('request.jwt.claim.sub','00005827-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($q$ select * from private.note_voice_jobs $q$,'42501',null,'private schema is not directly exposed to authenticated clients');
reset role;
-- Disposable transaction-only USAGE permits exercising the table policy independently.
grant usage on schema private to authenticated;
set local role authenticated;
select is((select count(*)::int from private.note_voice_jobs),1,'actor sees only own artifact jobs in shared workspace');
select is((select count(*)::int from private.note_voice_jobs where user_id='00005827-0000-4000-8000-000000000002'),0,'other actor artifacts hidden');
select throws_ok($q$ update private.note_voice_jobs set status='completed' $q$,'42501',null,'authenticated cannot forge job completion');
select throws_ok($q$ delete from private.note_voice_jobs $q$,'42501',null,'authenticated cannot bypass checked deletion');
select throws_ok($q$ insert into private.note_voice_jobs(id,ws_id,user_id,input_hash,timezone) values(gen_random_uuid(),'00005827-0000-4000-8000-000000000011','00005827-0000-4000-8000-000000000001',repeat('c',64),'UTC') $q$,'42501',null,'authenticated cannot bypass billing to create jobs');
reset role;
delete from public.workspace_members where ws_id='00005827-0000-4000-8000-000000000011' and user_id='00005827-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::int from private.note_voice_jobs),0,'revoked membership hides own retained artifacts');
reset role;
set local role anon;
select throws_ok($q$ select * from private.note_voice_jobs $q$,'42501',null,'anonymous cannot read voice artifacts');
reset role;
select * from finish();
rollback;
